  margin: 0;
  padding: 0;
}

/* ===== Skip link ===== */
.skip-link {
  position: absolute;
  top: -999px;
  left: 1rem;
  z-index: 100;
  padding: 0.5rem 1rem;
  background: #6366f1;
  color: #fff;
  font-weight: 600;
  border-radius: 0 0 6px 6px;
  text-decoration: none;
  transition: top 0.1s;
}
.skip-link:focus {
  top: 0;
}

/* ===== Tokens ===== */
:root {
  --color-bg:           #0d0f17;
  --color-surface:      #161928;
  --color-surface-alt:  #1e2237;
  --color-border:       #2e3354;
  --color-border-focus: #818cf8;
  --color-accent:       #6366f1;
  --color-accent-hover: #818cf8;
  --color-text:         #e2e8f0;
  --color-text-muted:   #94a3b8;
  --color-required:     #f87171;
  --color-success:      #4ade80;
  --color-error:        #f87171;
  --radius-card:        12px;
  --radius-control:     6px;
  --focus-ring:         0 0 0 3px rgba(129, 140, 248, 0.55);
}

/* ===== Layout ===== */
body {
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

header {
  border-bottom: 1px solid var(--color-border);
  padding: 1.25rem 2rem;
}

header h1 {
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--color-text);
  letter-spacing: 0.01em;
}

main {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 3rem 1.5rem;
}

/* ===== Card ===== */
.card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-card);
  padding: 2.5rem 2.25rem;
  width: 100%;
  max-width: 520px;
  box-shadow:
    0 4px 6px -1px rgba(0, 0, 0, 0.4),
    0 2px 4px -2px rgba(0, 0, 0, 0.3);
}

.card-heading {
  font-size: 1.375rem;
  font-weight: 700;
  margin-bottom: 0.375rem;
  color: var(--color-text);
}

.card-subheading {
  font-size: 0.9rem;
  color: var(--color-text-muted);
  margin-bottom: 2rem;
}

/* ===== Required legend ===== */
.required-note {
  font-size: 0.8rem;
  color: var(--color-text-muted);
  margin-bottom: 1.5rem;
  display: block;
}

.required-mark {
  color: var(--color-required);
  margin-right: 0.25rem;
  font-weight: 700;
}

/* ===== Form field wrapper ===== */
.form-field {
  margin-bottom: 2rem;
}

/* ===== Fieldset / Legend ===== */
fieldset {
  border: none;
  padding: 0;
}

legend {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 1rem;
  display: flex;
  align-items: center;
  gap: 0.25rem;
  width: 100%;
}

legend .required-mark {
  font-size: 0.9rem;
}

/* ===== Radio Options ===== */
.radio-options {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.radio-label {
  display: flex;
  align-items: center;
  gap: 0.875rem;
  padding: 0.875rem 1rem;
  background: var(--color-surface-alt);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-control);
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
  font-size: 0.95rem;
  color: var(--color-text);
  user-select: none;
}

.radio-label:hover {
  border-color: var(--color-accent-hover);
  background: rgba(99, 102, 241, 0.06);
}

/* Custom radio visuals */
.radio-label input[type="radio"] {
  appearance: none;
  -webkit-appearance: none;
  width: 1.125rem;
  height: 1.125rem;
  min-width: 1.125rem;
  border: 2px solid var(--color-border);
  border-radius: 50%;
  background: transparent;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s, box-shadow 0.15s;
  position: relative;
}

.radio-label input[type="radio"]::after {
  content: "";
  display: block;
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  background: var(--color-accent);
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) scale(0);
  transition: transform 0.15s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.radio-label input[type="radio"]:checked {
  border-color: var(--color-accent);
  background: rgba(99, 102, 241, 0.12);
}

.radio-label input[type="radio"]:checked::after {
  transform: translate(-50%, -50%) scale(1);
}

/* Selected card highlight */
.radio-label:has(input[type="radio"]:checked) {
  border-color: var(--color-accent);
  background: rgba(99, 102, 241, 0.08);
}

/* Focus ring on input */
.radio-label input[type="radio"]:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

/* Icon column */
.radio-icon {
  margin-left: auto;
  font-size: 1.1rem;
  opacity: 0.7;
}

/* ===== Option text ===== */
.radio-option-text {
  display: flex;
  flex-direction: column;
  flex: 1;
}

.radio-option-name {
  font-weight: 500;
}

.radio-option-desc {
  font-size: 0.8rem;
  color: var(--color-text-muted);
  line-height: 1.4;
}

/* ===== Submit Button ===== */
.btn-submit {
  width: 100%;
  padding: 0.875rem 1.5rem;
  background: var(--color-accent);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-control);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
  letter-spacing: 0.01em;
}

.btn-submit:hover {
  background: var(--color-accent-hover);
  box-shadow: 0 4px 14px rgba(99, 102, 241, 0.4);
}

.btn-submit:active {
  transform: scale(0.98);
}

.btn-submit:focus-visible {
  outline: none;
  box-shadow: var(--focus-ring);
}

/* ===== Status message ===== */
.status-message {
  border-radius: var(--radius-control);
  padding: 0.875rem 1rem;
  font-size: 0.9rem;
  font-weight: 500;
  margin-top: 1.25rem;
  display: none;
  align-items: center;
  gap: 0.5rem;
}

.status-message[data-visible="true"] {
  display: flex;
}

.status-message--success {
  background: rgba(74, 222, 128, 0.1);
  border: 1px solid rgba(74, 222, 128, 0.35);
  color: var(--color-success);
}

.status-message--error {
  background: rgba(248, 113, 113, 0.1);
  border: 1px solid rgba(248, 113, 113, 0.35);
  color: var(--color-error);
}

/* ===== Footer ===== */
footer {
  padding: 1.25rem 2rem;
  border-top: 1px solid var(--color-border);
  text-align: center;
  font-size: 0.8rem;
  color: var(--color-text-muted);
}

/* ===== Forced Colors / High Contrast ===== */
@media (forced-colors: active) {
  .radio-label {
    border: 2px solid ButtonText;
  }
  .radio-label:has(input[type="radio"]:checked) {
    border-color: Highlight;
  }
  .radio-label input[type="radio"]:checked {
    forced-color-adjust: none;
    background: Highlight;
    border-color: Highlight;
  }
  .btn-submit {
    forced-color-adjust: none;
    background: ButtonFace;
    color: ButtonText;
    border: 2px solid ButtonText;
  }
}

/* ===== Reduced motion ===== */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

/* ===== Reflow (320px) ===== */
@media (max-width: 400px) {
  .card {
    padding: 1.5rem 1.25rem;
  }
  .radio-label {
    padding: 0.75rem 0.875rem;
  }
}
