+/**
+ * NotificationForm — React-style component logic in vanilla JS.
+ *
+ * Components:
+ *   NotificationForm  — manages form state, validation, submission
+ *   RadioOption       — renders and wires a single radio option
+ *   StatusMessage     — renders a live-region status banner
+ */
+
+/* ---- StatusMessage ---- */
+function StatusMessage({ container }) {
+  function show({ type, text }) {
+    container.className = `status-message status-message--${type}`;
+    container.dataset.visible = "true";
+    container.innerHTML =
+      `<span aria-hidden="true">${type === "success" ? "✓" : "✕"}</span>${text}`;
+  }
+
+  function hide() {
+    container.dataset.visible = "false";
+    container.textContent = "";
+  }
+
+  return { show, hide };
+}
+
+/* ---- RadioOption ---- */
+function RadioOption({ name, value, id, labelText, description, icon }) {
+  const label = document.createElement("label");
+  label.className = "radio-label";
+  label.htmlFor = id;
+
+  const input = document.createElement("input");
+  input.type = "radio";
+  input.name = name;
+  input.value = value;
+  input.id = id;
+  input.required = true;
+
+  const textWrap = document.createElement("span");
+  textWrap.className = "radio-option-text";
+
+  const nameSpan = document.createElement("span");
+  nameSpan.className = "radio-option-name";
+  nameSpan.textContent = labelText;
+
+  const descSpan = document.createElement("span");
+  descSpan.className = "radio-option-desc";
+  descSpan.textContent = description;
+
+  textWrap.appendChild(nameSpan);
+  textWrap.appendChild(descSpan);
+
+  const iconSpan = document.createElement("span");
+  iconSpan.className = "radio-icon";
+  iconSpan.setAttribute("aria-hidden", "true");
+  iconSpan.textContent = icon;
+
+  label.appendChild(input);
+  label.appendChild(textWrap);
+  label.appendChild(iconSpan);
+
+  return label;
+}
+
+/* ---- NotificationForm ---- */
+function NotificationForm({ formEl, statusEl }) {
+  const status = StatusMessage({ container: statusEl });
+
+  const options = [
+    {
+      value: "email",
+      id: "notif-email",
+      labelText: "Email",
+      description: "Receive updates directly in your inbox.",
+      icon: "✉️",
+    },
+    {
+      value: "sms",
+      id: "notif-sms",
+      labelText: "SMS",
+      description: "Get instant text messages on your phone.",
+      icon: "💬",
+    },
+    {
+      value: "push",
+      id: "notif-push",
+      labelText: "Push Notifications",
+      description: "In-app alerts delivered in real time.",
+      icon: "🔔",
+    },
+  ];
+
+  // Render options into the .radio-options container
+  const optionsContainer = formEl.querySelector(".radio-options");
+  options.forEach((opt) => {
+    const el = RadioOption({ name: "notification-preference", ...opt });
+    optionsContainer.appendChild(el);
+  });
+
+  // Form submission handler
+  formEl.addEventListener("submit", function (e) {
+    e.preventDefault();
+    status.hide();
+
+    const selected = formEl.querySelector(
+      'input[name="notification-preference"]:checked'
+    );
+
+    if (!selected) {
+      status.show({
+        type: "error",
+        text: "Error: Please select a notification preference before submitting.",
+      });
+      // Focus the first radio so keyboard users can correct easily
+      const first = formEl.querySelector('input[name="notification-preference"]');
+      if (first) first.focus();
+      return;
+    }
+
+    const labelEl = formEl.querySelector(`label[for="${selected.id}"]`);
+    const choiceName = labelEl
+      ? labelEl.querySelector(".radio-option-name").textContent
+      : selected.value;
+
+    status.show({
+      type: "success",
+      text: `Preference saved! You'll receive notifications via ${choiceName}.`,
+    });
+  });
+}
+
+/* ---- Boot ---- */
+document.addEventListener("DOMContentLoaded", function () {
+  const formEl = document.getElementById("notification-form");
+  const statusEl = document.getElementById("form-status");
+
+  if (formEl && statusEl) {
+    NotificationForm({ formEl, statusEl });
+  }
+});
+
')

