// Find minimal darkening of #6366f1 that gives ≥4.5:1 contrast against white
function lin(c) {
  const s = c / 255;
  return s <= 0.04045 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
}
function lum(r, g, b) {
  return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b);
}
function contrast(L1, L2) {
  const [hi, lo] = L1 > L2 ? [L1, L2] : [L2, L1];
  return (hi + 0.05) / (lo + 0.05);
}
const Lwhite = 1.0;
// Try darkening from #6366f1 by stepping down RGB proportionally
for (let step = 0; step <= 30; step++) {
  const r = Math.max(0, 0x63 - step);
  const g = Math.max(0, 0x66 - step);
  const b = Math.max(0, 0xf1 - step);
  const L = lum(r, g, b);
  const c = contrast(Lwhite, L);
  if (c >= 4.5) {
    const hex = '#' + [r,g,b].map(x=>x.toString(16).padStart(2,'0')).join('');
    console.log(`${hex}  contrast=${c.toFixed(3)}  step=${step}`);
    break;
  }
}
